import { forwardRef } from 'react';

const DemoButton = forwardRef((props, ref) => {
  const handleClick = () => { /* ... */ };

  useExpose(ref, {
    componentName: 'DemoButton',
    methods: {
      onClick: {
        handler: handleClick,
        description: '\u6309\u94AE\u70B9\u51FB\u4E8B\u4EF6',
      },
    },
  });

  return <button onClick={handleClick}>\u70B9\u51FB\u6211</button>;
});
